messages.content:
Tool response:
Tool: add_july_tent_surcharge
Description: Add July Tent Surcharge
Parameters:
    {
      "type": "object",
      "properties": {
        "surcharge_amount": {
          "type": "number",
          "title": "Surcharge Amount",
          "description": "The surcharge amount to apply per night"
        },
        "start_date": {
          "type": "string",
          "title": "Start Date",
          "description": "Start date for the surcharge period (YYYY-MM-DD)"
        },
        "end_date": {
          "type": "string",
          "title": "End Date",
          "description": "End date for the surcharge period (YYYY-MM-DD)"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description",
          "description": "Optional description for the surcharge"
        }
      },
      "required": [
        "surcharge_amount",
        "start_date",
        "end_date"
      ]
    }
